@GameTestHolder("jdte") @PrefixGameTestTemplate(false)
public final class BioExtractorTierGameTests {
 private static final BlockPos POS=new BlockPos(2,1,2);
 private static UseOnContext ctx(GameTestHelper h,ItemStack item){var p=h.makeMockSurvivalPlayer();p.setItemInHand(InteractionHand.MAIN_HAND,item);return new UseOnContext(p,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(h.absolutePos(POS)),Direction.UP,h.absolutePos(POS),false));}
 private static AdvancedBioExtractorBE source(GameTestHelper h){h.setBlock(POS,JDTEBlocks.ADVANCED_BIO_EXTRACTOR.get());var b=(AdvancedBioExtractorBE)h.getBlockEntity(POS);var u=UpgradeHelper.getUpgradeHandler(b);for(int i=0;i<4;i++)u.insertItem(i,new ItemStack(i==0?JDTEItems.CAPACITY_UPGRADE.get():i==3?JDTEItems.OVERCLOCK_UPGRADE.get():JDTEItems.FILTER_UPGRADE.get()),false);b.getEnergyStorage().setEnergy(140000);b.getFluidTank().setFluid(new FluidStack(net.minecraftforge.common.ForgeMod.MILK.get(),30000));b.getMachineHandler().setStackInSlot(8,new ItemStack(Items.EGG,31));b.getFilterHandler().setStackInSlot(26,new ItemStack(Items.COW_SPAWN_EGG));var data=b.saveWithFullMetadata();data.putInt("tickCounter",17);data.putInt("acceleratedTicks",11);b.load(data);return b;}
 @GameTest(template="mineral_empty") public static void actualUpgradeMovesNineOutputsToEighteenAndAllActiveStorage(GameTestHelper h){
  var old=source(h);var oldItems=old.getCapability(net.minecraftforge.common.capabilities.ForgeCapabilities.ITEM_HANDLER).orElseThrow(IllegalStateException::new);var card=new ItemStack(JDTEItems.EXTENDED_UPGRADE.get());h.assertTrue(card.useOn(ctx(h,card))==InteractionResult.SUCCESS&&card.isEmpty(),"real new nineteenth Extended conversion succeeds");var b=(ExtendedBioExtractorBE)h.getBlockEntity(POS);
  h.assertTrue(b.getMachineHandler().getSlots()==18&&b.getMachineHandler().getStackInSlot(8).getCount()==31&&b.getMachineHandler().getStackInSlot(17).isEmpty()&&b.getEnergyStorage().getEnergyStored()==140000&&b.getFluidTank().getFluidAmount()==30000,"all physical output/FE/fluid storage migrates");
  h.assertTrue(UpgradeHelper.getUpgradeHandler(b).getSlots()==8&&UpgradeHelper.getUpgradeHandler(b).getStackInSlot(3).is(JDTEItems.OVERCLOCK_UPGRADE.get())&&b.getFilterHandler().getStackInSlot(26).is(Items.COW_SPAWN_EGG)&&b.getScanProgress()==17&&b.saveWithFullMetadata().getInt("acceleratedTicks")==11,"cards, last filter page and both progress counters preserved");h.assertTrue(oldItems.extractItem(8,31,false).isEmpty()&&old.getEnergyStorage().getEnergyStored()==0,"detached public item port and raw old FE have no second resources");h.succeed();
 }
 @GameTest(template="mineral_empty") public static void protectionDenialRestoresEntireBioStateAndCard(GameTestHelper h){
  var old=source(h);var before=old.saveWithFullMetadata();var called=new int[1];java.util.function.Consumer<net.minecraftforge.event.level.BlockEvent.EntityPlaceEvent> deny=e->{if(e.getLevel()==h.getLevel()&&e.getPos().equals(old.getBlockPos())){called[0]++;e.setCanceled(true);}};
  net.minecraftforge.common.MinecraftForge.EVENT_BUS.addListener(net.minecraftforge.eventbus.api.EventPriority.NORMAL,false,net.minecraftforge.event.level.BlockEvent.EntityPlaceEvent.class,deny);
  try{var card=new ItemStack(JDTEItems.EXTENDED_UPGRADE.get());h.assertTrue(card.useOn(ctx(h,card))==InteractionResult.FAIL&&card.getCount()==1&&called[0]==1&&((AdvancedBioExtractorBE)h.getBlockEntity(POS)).saveWithFullMetadata().equals(before),"actual Forge protection rollback preserves exact unique NBT/resources and conversion card");}finally{net.minecraftforge.common.MinecraftForge.EVENT_BUS.unregister(deny);}h.succeed();
 }
 @GameTest(template="mineral_empty") public static void packedCraftingAndActualWrenchPlacementRetainBioResources(GameTestHelper h){
  var b=source(h);var old=new ItemStack(JDTEItems.ADVANCED_BIO_EXTRACTOR.get());old.getOrCreateTag().put("JustDiresBEData",b.saveWithoutMetadata());var input=new net.minecraft.world.inventory.TransientCraftingContainer(new net.minecraft.world.inventory.AbstractContainerMenu(null,0){public boolean stillValid(net.minecraft.world.entity.player.Player p){return true;}public ItemStack quickMoveStack(net.minecraft.world.entity.player.Player p,int i){return ItemStack.EMPTY;}},3,3);input.setItem(1,new ItemStack(JDTEItems.EXTENDED_UPGRADE.get()));input.setItem(4,old);
  var recipe=(net.minecraft.world.item.crafting.CraftingRecipe)h.getLevel().getRecipeManager().byKey(com.jdte.JDTE.id("extended_bio_extractor")).orElseThrow();h.assertTrue(recipe.matches(input,h.getLevel()),"registered packed crafting recipe matches");var output=recipe.assemble(input,h.getLevel().registryAccess());h.setBlock(POS,JDTEBlocks.EXTENDED_BIO_EXTRACTOR.get());var ext=(ExtendedBioExtractorBE)h.getBlockEntity(POS);ext.load(output.getTag().getCompound("JustDiresBEData"));h.assertTrue(ext.getMachineHandler().getSlots()==18&&ext.getEnergyStorage().getEnergyStored()==140000&&ext.getFluidTank().getFluidAmount()==30000&&UpgradeHelper.getUpgradeHandler(ext).getStackInSlot(3).is(JDTEItems.OVERCLOCK_UPGRADE.get()),"packed recipe keeps source state and expands real inventory");
  var p=h.makeMockSurvivalPlayer();p.setPos(ext.getBlockPos().getX()+.5,ext.getBlockPos().getY()+1,ext.getBlockPos().getZ()+.5);h.assertTrue(EclipseAlloyWrenchItem.pickupMachine(h.getLevel(),ext.getBlockPos(),p),"actual wrench packs extractor");var packed=p.getInventory().items.stream().filter(s->s.is(JDTEItems.EXTENDED_BIO_EXTRACTOR.get())).findFirst().orElseThrow();p.setItemInHand(InteractionHand.MAIN_HAND,packed);h.assertTrue(packed.useOn(new UseOnContext(p,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(h.absolutePos(POS)),Direction.UP,h.absolutePos(POS),false))).consumesAction(),"actual packed BlockItem placement");var fresh=(ExtendedBioExtractorBE)h.getBlockEntity(POS);h.assertTrue(fresh.getMachineHandler().getStackInSlot(8).getCount()==31&&fresh.getEnergyStorage().getEnergyStored()==140000&&fresh.getFluidTank().getFluidAmount()==30000&&fresh.getScanProgress()==17,"placed packed extractor retains outputs, FE, fluid and progress");h.succeed();
 }
 @GameTest(template="mineral_empty") public static void filledLifePrerequisiteCraftRetainsBuffersAndRejectsUnconvertedFraction(GameTestHelper h){
  h.setBlock(POS,JDTEBlocks.ADVANCED_LIFE_EXTRACTOR.get());var life=(AdvancedLifeExtractorBE)h.getBlockEntity(POS);UpgradeHelper.getUpgradeHandler(life).insertItem(0,new ItemStack(JDTEItems.CAPACITY_UPGRADE.get()),false);life.getEnergyStorage().setEnergy(45000);life.getFluidTank().setFluid(new FluidStack(JDTEFluids.LIFE_FLUID_SOURCE.get(),2000));var box=new ItemStack(JDTEItems.ADVANCED_LIFE_EXTRACTOR.get());box.getOrCreateTag().put("JustDiresBEData",life.saveWithoutMetadata());var input=new net.minecraft.world.inventory.TransientCraftingContainer(new net.minecraft.world.inventory.AbstractContainerMenu(null,0){public boolean stillValid(net.minecraft.world.entity.player.Player p){return true;}public ItemStack quickMoveStack(net.minecraft.world.entity.player.Player p,int i){return ItemStack.EMPTY;}},3,3);
  var ingredients=List.of(new ItemStack(Items.SHEARS),new ItemStack(Items.DIAMOND),new ItemStack(Items.BUCKET),new ItemStack(Items.REDSTONE_BLOCK),box,new ItemStack(Items.REDSTONE_BLOCK),new ItemStack(Items.BUCKET),new ItemStack(Items.DIAMOND),new ItemStack(Items.SHEARS));for(int k=0;k<9;k++)input.setItem(k,ingredients.get(k));var recipe=(net.minecraft.world.item.crafting.CraftingRecipe)h.getLevel().getRecipeManager().byKey(com.jdte.JDTE.id("advanced_bio_extractor")).orElseThrow();h.assertTrue(recipe.matches(input,h.getLevel()),"actual filled prerequisite recipe");var result=recipe.assemble(input,h.getLevel().registryAccess());h.setBlock(POS,JDTEBlocks.ADVANCED_BIO_EXTRACTOR.get());var bio=(AdvancedBioExtractorBE)h.getBlockEntity(POS);bio.load(result.getTag().getCompound("JustDiresBEData"));h.assertTrue(bio.getEnergyStorage().getEnergyStored()==45000&&bio.getFluidTank().getFluidAmount()==2000&&bio.getFluidTank().getFluid().getFluid()==JDTEFluids.LIFE_FLUID_SOURCE.get()&&UpgradeHelper.countUpgrades(bio,com.jdte.common.upgrades.UpgradeType.CAPACITY)==1&&bio.getMachineHandler().getSlots()==9,"construction preserves actual FE/Life Fluid/four-slot card and real nine output slots");box.getTag().getCompound("JustDiresBEData").putDouble("pendingLifeFluid",.25);h.assertTrue(!recipe.matches(input,h.getLevel()),"unrepresentable pending source fraction cannot disappear in crafting");h.succeed();
 }
 @GameTest(template="mineral_empty") public static void normalBreakDropsOutputsOnceAndRemovesPackedDuplicateData(GameTestHelper h){
  h.setBlock(POS,JDTEBlocks.EXTENDED_BIO_EXTRACTOR.get());var b=(ExtendedBioExtractorBE)h.getBlockEntity(POS);var invocation=UUID.randomUUID();var eggs=new ItemStack(Items.EGG,31);eggs.getOrCreateTag().putUUID("bio_break_fixture",invocation);b.getMachineHandler().setStackInSlot(17,eggs);
  var blocks=new java.util.ArrayList<UUID>();java.util.function.Consumer<net.minecraftforge.event.entity.EntityJoinLevelEvent> capture=e->{if(!e.loadedFromDisk()&&e.getEntity() instanceof net.minecraft.world.entity.item.ItemEntity drop&&drop.getItem().is(JDTEItems.EXTENDED_BIO_EXTRACTOR.get())&&new AABB(h.absolutePos(POS)).inflate(3).contains(drop.position()))blocks.add(drop.getUUID());};
  net.minecraftforge.common.MinecraftForge.EVENT_BUS.addListener(net.minecraftforge.eventbus.api.EventPriority.LOWEST,false,net.minecraftforge.event.entity.EntityJoinLevelEvent.class,capture);
  try{h.getLevel().destroyBlock(b.getBlockPos(),true);}finally{net.minecraftforge.common.MinecraftForge.EVENT_BUS.unregister(capture);}
  h.runAfterDelay(2,()->{int count=0,blockCount=0;for(var drop:h.getLevel().getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new AABB(h.absolutePos(POS)).inflate(3))){var stack=drop.getItem();if(stack.is(Items.EGG)&&stack.hasTag()&&stack.getTag().hasUUID("bio_break_fixture")&&stack.getTag().getUUID("bio_break_fixture").equals(invocation))count+=stack.getCount();if(blocks.contains(drop.getUUID())){blockCount+=stack.getCount();var data=stack.hasTag()?stack.getTag().getCompound("JustDiresBEData"):new net.minecraft.nbt.CompoundTag();h.assertTrue(!data.contains("itemHandler")&&!data.contains("machineHandler"),"normal block drop cannot carry another output inventory");}}h.assertTrue(blockCount==1&&count==31,"this actual break scatters exactly thirty-one outputs plus one machine; outputs="+count+", blocks="+blockCount);h.succeed();});
 }
 @GameTest(template="mineral_empty") public static void copierUsesBothStorageBagsAndPreservesTargetProducts(GameTestHelper h){
  var from=source(h);var other=new BlockPos(5,1,2);h.setBlock(other,JDTEBlocks.ADVANCED_BIO_EXTRACTOR.get());var target=(AdvancedBioExtractorBE)h.getBlockEntity(other);target.getMachineHandler().setStackInSlot(8,new ItemStack(Items.BLUE_WOOL,5));target.getEnergyStorage().setEnergy(23456);target.getFluidTank().setFluid(new FluidStack(net.minecraftforge.common.ForgeMod.MILK.get(),1000));var tool=new ItemStack(JDTEItems.ADVANCED_MACHINE_SETTINGS_COPIER.get());JDTEItems.ADVANCED_MACHINE_SETTINGS_COPIER.get().saveSettings(from,tool);var p=h.makeMockSurvivalPlayer();p.setItemInHand(InteractionHand.MAIN_HAND,tool);var basic=new ItemStack(JDTEItems.UPGRADE_STORAGE.get());var advanced=new ItemStack(JDTEItems.ADVANCED_UPGRADE_STORAGE.get());var one=new com.jdte.common.containers.handlers.UpgradeStorageHandler(basic);var two=new com.jdte.common.containers.handlers.AdvancedUpgradeStorageHandler(advanced);one.insertItem(19,new ItemStack(JDTEItems.CAPACITY_UPGRADE.get()),false);two.insertItem(34,new ItemStack(JDTEItems.FILTER_UPGRADE.get(),2),false);two.insertItem(35,new ItemStack(JDTEItems.OVERCLOCK_UPGRADE.get()),false);p.getInventory().setItem(9,basic);p.setItemInHand(InteractionHand.OFF_HAND,advanced);var context=new UseOnContext(p,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(h.absolutePos(other)),Direction.UP,h.absolutePos(other),false));var crossPos=new BlockPos(5,1,4);h.setBlock(crossPos,JDTEBlocks.EXTENDED_BIO_EXTRACTOR.get());var cross=(ExtendedBioExtractorBE)h.getBlockEntity(crossPos);var crossBefore=cross.saveWithFullMetadata();var wrong=new UseOnContext(p,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(h.absolutePos(crossPos)),Direction.UP,h.absolutePos(crossPos),false));h.assertTrue(JDTEItems.ADVANCED_MACHINE_SETTINGS_COPIER.get().useOn(wrong)==InteractionResult.PASS&&cross.saveWithFullMetadata().equals(crossBefore)&&one.getStackInSlot(19).getCount()==1&&two.getStackInSlot(34).getCount()==2,"source copier strict type guard rejects cross-tier paste without spending cards or changing state");h.assertTrue(JDTEItems.ADVANCED_MACHINE_SETTINGS_COPIER.get().useOn(context)==InteractionResult.SUCCESS,"actual copier consumes cards from both bag types for new Bio target");h.assertTrue(one.getStackInSlot(19).isEmpty()&&two.getStackInSlot(34).isEmpty()&&two.getStackInSlot(35).isEmpty()&&UpgradeHelper.countUpgrades(target,com.jdte.common.upgrades.UpgradeType.FILTER)==2,"exact bag card consumption");h.assertTrue(target.getMachineHandler().getStackInSlot(8).getCount()==5&&target.getEnergyStorage().getEnergyStored()==23456&&target.getFluidTank().getFluidAmount()==1000,"configuration does not copy or erase production buffers");h.assertTrue(JDTEItems.ADVANCED_MACHINE_SETTINGS_COPIER.get().useOn(context)==InteractionResult.SUCCESS,"repeat paste requires no additional cards");h.succeed();
 }
 @GameTest(template="mineral_empty") public static void bulkCopierCapacityDowngradeIsAtomicAndDoesNotClipBioBuffers(GameTestHelper h){
  h.setBlock(POS,JDTEBlocks.ADVANCED_BIO_EXTRACTOR.get());var empty=(AdvancedBioExtractorBE)h.getBlockEntity(POS);var tool=new ItemStack(JDTEItems.ADVANCED_MACHINE_SETTINGS_COPIER.get());JDTEItems.ADVANCED_MACHINE_SETTINGS_COPIER.get().saveSettings(empty,tool);var other=new BlockPos(5,1,2);h.setBlock(other,JDTEBlocks.ADVANCED_BIO_EXTRACTOR.get());var b=(AdvancedBioExtractorBE)h.getBlockEntity(other);UpgradeHelper.getUpgradeHandler(b).insertItem(3,new ItemStack(JDTEItems.ULTIMATE_CAPACITY_UPGRADE.get()),false);b.getEnergyStorage().setEnergy(b.getMaxEnergy());b.getFluidTank().setFluid(new FluidStack(net.minecraftforge.common.ForgeMod.MILK.get(),20000));var before=b.saveWithFullMetadata();var p=h.makeMockSurvivalPlayer();p.setItemInHand(InteractionHand.MAIN_HAND,tool);var context=new UseOnContext(p,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(h.absolutePos(other)),Direction.UP,h.absolutePos(other),false));h.assertTrue(JDTEItems.ADVANCED_MACHINE_SETTINGS_COPIER.get().useOn(context)==InteractionResult.PASS&&b.saveWithFullMetadata().equals(before)&&p.getInventory().countItem(JDTEItems.ULTIMATE_CAPACITY_UPGRADE.get())==0,"complete upgrade-layout preflight rejects unsafe bulk downgrade without changing FE/fluid/cards");
  var same=new ItemStack(JDTEItems.ADVANCED_MACHINE_SETTINGS_COPIER.get());JDTEItems.ADVANCED_MACHINE_SETTINGS_COPIER.get().saveSettings(b,same);p.setItemInHand(InteractionHand.MAIN_HAND,same);var sameContext=new UseOnContext(p,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(h.absolutePos(other)),Direction.UP,h.absolutePos(other),false));h.assertTrue(JDTEItems.ADVANCED_MACHINE_SETTINGS_COPIER.get().useOn(sameContext)==InteractionResult.SUCCESS&&b.getEnergyStorage().getEnergyStored()==5000000&&b.getFluidTank().getFluidAmount()==20000,"late-slot Ultimate layout validates as a whole while full");p.setItemInHand(InteractionHand.MAIN_HAND,tool);b.getEnergyStorage().setEnergy(0);b.getFluidTank().setFluid(new FluidStack(net.minecraftforge.common.ForgeMod.MILK.get(),1000));h.assertTrue(JDTEItems.ADVANCED_MACHINE_SETTINGS_COPIER.get().useOn(context)==InteractionResult.SUCCESS&&p.getInventory().countItem(JDTEItems.ULTIMATE_CAPACITY_UPGRADE.get())==1&&b.getFluidTank().getFluidAmount()==1000,"safe drained downgrade returns card exactly once");h.succeed();
 }
}
